from __future__ import annotations

from html import escape

from fastapi import APIRouter, Request
from fastapi.responses import HTMLResponse, RedirectResponse

from .branding import PRODUCT_FULL_NAME
from .plans import GAME_CREATE

router = APIRouter(tags=["Game Forge Visual Logic Portal"])


@router.get(
    "/game-creation/visual-logic/{game_id}/{entity_id}",
    response_class=HTMLResponse,
    include_in_schema=False,
)
def visual_logic_portal(game_id: str, entity_id: str, request: Request):
    member = getattr(request.state, "member", None)
    if member is None:
        next_path = f"/game-creation/visual-logic/{escape(game_id, quote=True)}/{escape(entity_id, quote=True)}"
        return RedirectResponse(f"/signin?next={next_path}", status_code=303)
    if not member.plan.has(GAME_CREATE):
        return RedirectResponse("/game-creation", status_code=303)

    safe_game_id = escape(game_id, quote=True)
    safe_entity_id = escape(entity_id, quote=True)
    safe_brand = escape(PRODUCT_FULL_NAME)
    html = r"""<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='robots' content='noindex,nofollow'><title>Visual Logic — __BRAND__</title><style>
:root{--bg:#04050b;--panel:#0b1020;--line:#ffffff24;--gold:#efca6d;--violet:#986cff;--cyan:#5be1ff;--green:#79dda5;--red:#ff8fa5;--muted:#b9c4d6}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 4% 0,#42176466,transparent 35%),radial-gradient(circle at 96% 4%,#0e526355,transparent 31%),var(--bg);color:#fff;font-family:Inter,system-ui,sans-serif}.wrap{width:min(1500px,calc(100% - 20px));margin:auto}.nav{position:sticky;top:0;z-index:30;background:#05070eef;border-bottom:1px solid var(--line);backdrop-filter:blur(14px)}.navin{min-height:66px;display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}.brand{font-weight:950;color:#fff;text-decoration:none}.brand small{display:block;color:var(--gold);font-size:.64rem;letter-spacing:.12em;text-transform:uppercase}.btn,button{border:1px solid var(--line);background:#ffffff08;color:#fff;border-radius:10px;padding:9px 11px;font:inherit;font-weight:850;cursor:pointer;text-decoration:none}.primary{border:0;background:linear-gradient(120deg,var(--gold),var(--violet));color:#160c1d}.danger{border-color:#ff8fa566;color:#ffc5d0}.hero{padding:28px 0 14px}.eyebrow{color:var(--gold);font-size:.68rem;font-weight:950;letter-spacing:.14em;text-transform:uppercase}h1{font-size:clamp(2.2rem,5vw,4.7rem);line-height:.95;letter-spacing:-.045em;margin:.1em 0}.muted{color:var(--muted);line-height:1.5}.layout{display:grid;grid-template-columns:280px minmax(0,1fr) 300px;gap:10px;padding-bottom:50px}.card{border:1px solid var(--line);border-radius:16px;background:linear-gradient(145deg,#11172be8,#080c17ef);padding:13px}.palette{display:grid;gap:8px}.palette button{text-align:left}.palette b{display:block}.palette small{display:block;color:var(--muted);margin-top:3px}.sectionLabel{margin:12px 0 5px;color:var(--cyan);font-size:.65rem;font-weight:950;letter-spacing:.12em;text-transform:uppercase}.canvasWrap{position:relative;min-height:650px;border:1px solid var(--line);border-radius:17px;background-color:#070a12;background-image:linear-gradient(#ffffff08 1px,transparent 1px),linear-gradient(90deg,#ffffff08 1px,transparent 1px);background-size:28px 28px;overflow:auto}.canvas{position:relative;min-width:1000px;min-height:650px}.wires{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;overflow:visible}.wire{stroke:#5be1ff99;stroke-width:2;fill:none}.node{position:absolute;width:230px;border:1px solid #ffffff33;border-radius:14px;background:#0d1425f2;box-shadow:0 14px 35px #0007;overflow:hidden}.nodeHead{display:flex;align-items:center;justify-content:space-between;gap:6px;padding:9px 10px;background:#ffffff08;cursor:grab;touch-action:none}.nodeHead b{font-size:.83rem}.nodeBody{display:grid;gap:7px;padding:10px}.node label{display:grid;gap:3px;color:var(--muted);font-size:.72rem}.node input,.node select,.side select{width:100%;border:1px solid var(--line);background:#060913;color:#fff;border-radius:8px;padding:7px;font:inherit}.node input[type=checkbox]{width:auto}.remove{padding:3px 7px;border-color:#ff8fa555;color:#ffbdc9}.pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:3px 7px;font-size:.68rem;margin:2px}.side{display:grid;gap:10px;align-content:start}.edgeRow{border:1px solid var(--line);border-radius:10px;padding:8px;margin-top:6px;background:#ffffff05}.notice{display:none;margin:10px 0;padding:10px;border:1px solid var(--line);border-radius:10px}.notice.show{display:block}.empty{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);color:var(--muted);text-align:center}.safe{border-left:3px solid var(--green)}.status{display:flex;gap:5px;flex-wrap:wrap;margin-top:8px}@media(max-width:1100px){.layout{grid-template-columns:240px minmax(0,1fr)}.side{grid-column:1/-1;grid-template-columns:repeat(2,1fr)}}@media(max-width:720px){.layout{grid-template-columns:1fr}.side{grid-column:auto;grid-template-columns:1fr}.canvasWrap{min-height:560px}}
</style></head><body><nav class='nav'><div class='wrap navin'><a class='brand' href='/game-creation'>__BRAND__<small>Aura Game Forge · Visual Logic</small></a><div><a class='btn' href='/game-creation/world-logic/__GAME_ID__'>World Logic</a> <button id='buildBtn'>Build & Play</button> <button id='saveBtn' class='primary'>Compile Graph</button></div></div></nav><main class='wrap'><section class='hero'><div class='eyebrow'>Executable typed node graph</div><h1 id='title'>Visual Logic</h1><p class='muted'>Author safe visual behaviors that compile directly into this World entity's executable Behavior DNA. Connections define deterministic compile order; they are not hidden arbitrary code flow.</p><div class='status'><span class='pill' id='revision'>Revision —</span><span class='pill'>8 runtime-backed ops</span><span class='pill'>No eval</span><span class='pill'>No runtime network</span><span class='pill'>Build-invalidating compile</span></div><div id='notice' class='notice'></div></section><section class='layout'><aside class='card'><div class='eyebrow'>Node palette</div><h2>Add behavior</h2><div class='palette'><div class='sectionLabel'>World logic</div><button data-add='follow_target'><b>Follow Target</b><small>Move a kinematic/dynamic entity toward an existing World entity.</small></button><button data-add='timer'><b>Timer</b><small>Fire a bounded Aura event message after a duration.</small></button><button data-add='door'><b>Automatic Door</b><small>Move a kinematic entity when the player enters its proximity radius.</small></button><div class='sectionLabel'>Aura3D gameplay</div><button data-add='collectible'><b>Collectible</b><small>Award bounded score on player collision, with optional respawn.</small></button><button data-add='damage'><b>Damage / Hazard</b><small>Apply bounded lives damage with cooldown and checkpoint reset.</small></button><button data-add='checkpoint'><b>Checkpoint</b><small>Save the player's current runtime checkpoint on collision.</small></button><button data-add='patrol'><b>Patrol</b><small>Move a kinematic/dynamic entity on a bounded axis patrol.</small></button><button data-add='quest_trigger'><b>Quest Trigger</b><small>Dispatch a bounded reach/event trigger when the player enters it.</small></button></div><div class='card safe' style='margin-top:12px'><div class='eyebrow'>Closed compiler</div><p class='muted'>Only runtime-verified node types are offered. Unknown parameters are removed server-side and JavaScript/Python source is never accepted by this graph.</p></div></aside><div class='canvasWrap' id='canvasWrap'><div class='canvas' id='canvas'><svg class='wires' id='wires'></svg><div class='empty' id='empty'>Add a node from the palette.</div></div></div><aside class='side'><div class='card'><div class='eyebrow'>Compile-order links</div><h3>Connect nodes</h3><select id='edgeSource'></select><select id='edgeTarget' style='margin-top:7px'></select><button id='addEdge' style='margin-top:7px'>Add link</button><div id='edges'></div></div><div class='card'><div class='eyebrow'>Graph actions</div><p class='muted'>Saving compiles immediately into World DNA and invalidates stale build/rating state. Collision nodes require Physics DNA; patrol/follow require movable Physics DNA. Use Build & Play after a successful compile.</p><button id='deleteBtn' class='danger'>Delete graph</button></div></aside></section></main><script>
'use strict';const GAME_ID='__GAME_ID__',ENTITY_ID='__ENTITY_ID__';const $=id=>document.getElementById(id);let nodes=[],edges=[],revision=null,drag=null;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function notice(v,bad=false){const e=$('notice');e.textContent=v;e.className='notice show';e.style.borderColor=bad?'#ff8fa566':'#79dda566';clearTimeout(window.__vlNotice);window.__vlNotice=setTimeout(()=>e.className='notice',6500)}async function api(url,opt={}){const r=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});let b={};try{b=await r.json()}catch{}if(!r.ok)throw new Error(typeof b.detail==='string'?b.detail:(b.detail?.message||JSON.stringify(b.detail)||`Request failed (${r.status})`));return b}
const TITLES={follow_target:'Follow Target',timer:'Timer',door:'Automatic Door',collectible:'Collectible',damage:'Damage / Hazard',checkpoint:'Checkpoint',patrol:'Patrol',quest_trigger:'Quest Trigger'};function uid(op){const raw=(globalThis.crypto?.randomUUID?.()||`${Date.now()}_${Math.random().toString(16).slice(2)}`).replace(/[^A-Za-z0-9_-]/g,'');return`${op}_${raw}`.slice(0,80)}function defaults(op){if(op==='follow_target')return{target:'player',speed:2,stop_distance:1.5};if(op==='timer')return{seconds:5,repeat:false,event:'Timer event'};if(op==='door')return{axis:'y',distance:3,speed:2,trigger_distance:2.5,auto_close:true,close_delay:1.5};if(op==='collectible')return{points:1,respawn:false,respawn_seconds:3};if(op==='damage')return{amount:1,reset_to_checkpoint:true,cooldown_seconds:.75};if(op==='checkpoint')return{label:'Checkpoint'};if(op==='patrol')return{axis:'x',distance:3,speed:1,ping_pong:true};return{event:'triggered',once:true}}
function axisField(p,def='x'){return`<label>Axis<select data-k='axis'><option value='x' ${(p.axis??def)==='x'?'selected':''}>X</option><option value='y' ${(p.axis??def)==='y'?'selected':''}>Y</option><option value='z' ${(p.axis??def)==='z'?'selected':''}>Z</option></select></label>`}function paramsHtml(n){const p=n.params||{};if(n.op==='follow_target')return`<label>Target entity ID<input data-k='target' value='${esc(p.target??'player')}' maxlength='160'></label><label>Speed<input data-k='speed' type='number' min='0' max='1000' step='.1' value='${Number(p.speed??2)}'></label><label>Stop distance<input data-k='stop_distance' type='number' min='0' max='100000' step='.1' value='${Number(p.stop_distance??1.5)}'></label>`;if(n.op==='timer')return`<label>Seconds<input data-k='seconds' type='number' min='.05' max='86400' step='.05' value='${Number(p.seconds??5)}'></label><label>Event text<input data-k='event' value='${esc(p.event??'Timer event')}' maxlength='160'></label><label><span>Repeat <input data-k='repeat' type='checkbox' ${p.repeat===true?'checked':''}></span></label>`;if(n.op==='door')return`${axisField(p,'y')}<label>Distance<input data-k='distance' type='number' min='0' max='100000' step='.1' value='${Number(p.distance??3)}'></label><label>Speed<input data-k='speed' type='number' min='.01' max='1000' step='.1' value='${Number(p.speed??2)}'></label><label>Trigger distance<input data-k='trigger_distance' type='number' min='.1' max='100000' step='.1' value='${Number(p.trigger_distance??2.5)}'></label><label>Close delay<input data-k='close_delay' type='number' min='0' max='3600' step='.1' value='${Number(p.close_delay??1.5)}'></label><label><span>Auto close <input data-k='auto_close' type='checkbox' ${p.auto_close!==false?'checked':''}></span></label>`;if(n.op==='collectible')return`<label>Points<input data-k='points' type='number' min='1' max='1000000' step='1' value='${Number(p.points??1)}'></label><label>Respawn seconds<input data-k='respawn_seconds' type='number' min='.25' max='3600' step='.25' value='${Number(p.respawn_seconds??3)}'></label><label><span>Respawn <input data-k='respawn' type='checkbox' ${p.respawn===true?'checked':''}></span></label>`;if(n.op==='damage')return`<label>Damage amount<input data-k='amount' type='number' min='1' max='1000' step='1' value='${Number(p.amount??1)}'></label><label>Cooldown seconds<input data-k='cooldown_seconds' type='number' min='.05' max='60' step='.05' value='${Number(p.cooldown_seconds??.75)}'></label><label><span>Reset to checkpoint <input data-k='reset_to_checkpoint' type='checkbox' ${p.reset_to_checkpoint!==false?'checked':''}></span></label>`;if(n.op==='checkpoint')return`<label>Label<input data-k='label' value='${esc(p.label??'Checkpoint')}' maxlength='80'></label>`;if(n.op==='patrol')return`${axisField(p,'x')}<label>Distance<input data-k='distance' type='number' min='0' max='100000' step='.1' value='${Number(p.distance??3)}'></label><label>Speed<input data-k='speed' type='number' min='0' max='1000' step='.1' value='${Number(p.speed??1)}'></label><label><span>Ping pong <input data-k='ping_pong' type='checkbox' ${p.ping_pong!==false?'checked':''}></span></label>`;return`<label>Event<input data-k='event' value='${esc(p.event??'triggered')}' maxlength='120'></label><label><span>Once <input data-k='once' type='checkbox' ${p.once!==false?'checked':''}></span></label>`}
function nodeTitle(op){return TITLES[op]||op}function render(){const canvas=$('canvas');canvas.querySelectorAll('.node').forEach(e=>e.remove());$('empty').style.display=nodes.length?'none':'block';for(const n of nodes){const el=document.createElement('article');el.className='node';el.dataset.id=n.id;el.style.left=`${Number(n.canvas_x||0)}px`;el.style.top=`${Number(n.canvas_y||0)}px`;el.innerHTML=`<div class='nodeHead' data-drag='1'><b>${esc(nodeTitle(n.op))}</b><button class='remove' data-remove='1' aria-label='Remove node'>×</button></div><div class='nodeBody'><label><span>Enabled <input data-enabled='1' type='checkbox' ${n.enabled!==false?'checked':''}></span></label>${paramsHtml(n)}<small class='muted'>${esc(n.id)}</small></div>`;canvas.appendChild(el)}renderEdges();bindNodes();syncEdgeSelects();$('revision').textContent=`Revision ${revision??'new'}`}
function nodeCenter(id){const e=document.querySelector(`.node[data-id="${CSS.escape(id)}"]`);if(!e)return null;return{x:e.offsetLeft+e.offsetWidth/2,y:e.offsetTop+e.offsetHeight/2}}function renderEdges(){const svg=$('wires');svg.innerHTML='';for(const edge of edges){const a=nodeCenter(edge.source),b=nodeCenter(edge.target);if(!a||!b)continue;const path=document.createElementNS('http://www.w3.org/2000/svg','path');const mx=(a.x+b.x)/2;path.setAttribute('class','wire');path.setAttribute('d',`M ${a.x} ${a.y} C ${mx} ${a.y}, ${mx} ${b.y}, ${b.x} ${b.y}`);svg.appendChild(path)}$('edges').innerHTML=edges.map((e,i)=>`<div class='edgeRow'><small>${esc(e.source)} → ${esc(e.target)}</small><button data-edge-remove='${i}' class='remove' style='float:right'>×</button></div>`).join('')||'<p class="muted">No compile-order links.</p>';$('edges').querySelectorAll('[data-edge-remove]').forEach(b=>b.addEventListener('click',()=>{edges.splice(Number(b.dataset.edgeRemove),1);renderEdges()}))}
function syncEdgeSelects(){const options=nodes.map(n=>`<option value='${esc(n.id)}'>${esc(nodeTitle(n.op))} · ${esc(n.id)}</option>`).join('');$('edgeSource').innerHTML=options;$('edgeTarget').innerHTML=options}function readNode(el){const n=nodes.find(x=>x.id===el.dataset.id);if(!n)return;n.canvas_x=el.offsetLeft;n.canvas_y=el.offsetTop;n.enabled=el.querySelector('[data-enabled]').checked;const p={};el.querySelectorAll('[data-k]').forEach(i=>{const k=i.dataset.k;if(i.type==='checkbox')p[k]=i.checked;else if(i.type==='number')p[k]=Number(i.value);else p[k]=i.value});n.params=p}
function bindNodes(){document.querySelectorAll('.node').forEach(el=>{el.querySelector('[data-remove]').addEventListener('click',()=>{nodes=nodes.filter(n=>n.id!==el.dataset.id);edges=edges.filter(e=>e.source!==el.dataset.id&&e.target!==el.dataset.id);render()});const head=el.querySelector('[data-drag]');head.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;drag={el,startX:e.clientX,startY:e.clientY,left:el.offsetLeft,top:el.offsetTop};head.setPointerCapture(e.pointerId)});head.addEventListener('pointermove',e=>{if(!drag||drag.el!==el)return;el.style.left=`${Math.max(0,drag.left+e.clientX-drag.startX)}px`;el.style.top=`${Math.max(0,drag.top+e.clientY-drag.startY)}px`;readNode(el);renderEdges()});head.addEventListener('pointerup',e=>{if(drag?.el===el){readNode(el);drag=null;try{head.releasePointerCapture(e.pointerId)}catch{}}});el.querySelectorAll('input,select').forEach(i=>i.addEventListener('change',()=>readNode(el)))})}
function addNode(op){const i=nodes.length;nodes.push({id:uid(op),op,params:defaults(op),enabled:true,canvas_x:30+(i%3)*260,canvas_y:35+Math.floor(i/3)*250});render()}document.querySelectorAll('[data-add]').forEach(b=>b.addEventListener('click',()=>addNode(b.dataset.add)));$('addEdge').addEventListener('click',()=>{const source=$('edgeSource').value,target=$('edgeTarget').value;if(!source||!target)return notice('Add at least two nodes first.',true);if(source===target)return notice('A node cannot link to itself.',true);if(edges.some(e=>e.source===source&&e.target===target))return notice('That link already exists.',true);edges.push({source,target});renderEdges()});
async function load(){try{const [game,state,world]=await Promise.all([api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}`),api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}/visual-logic/${encodeURIComponent(ENTITY_ID)}`),api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}/world`)]);const entity=(world.world?.entities||[]).find(e=>e.id===ENTITY_ID);if(!entity)throw new Error('World entity not found');$('title').textContent=`${game.title} · ${entity.name} Visual Logic`;if(state.graph){nodes=state.graph.nodes||[];edges=state.graph.edges||[];revision=state.graph.revision}else{nodes=[];edges=[];revision=null}render()}catch(e){notice(e.message,true)}}
$('saveBtn').addEventListener('click',async()=>{try{document.querySelectorAll('.node').forEach(readNode);const body={nodes,edges};if(revision!==null)body.expected_revision=revision;const r=await api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}/visual-logic/${encodeURIComponent(ENTITY_ID)}`,{method:'PUT',body:JSON.stringify(body)});nodes=r.graph.nodes||[];edges=r.graph.edges||[];revision=r.graph.revision;render();notice(`Visual Logic compiled into World DNA revision ${r.graph.compiled_world_revision}. Rebuild before playtest/public testing.`)}catch(e){notice(e.message,true)}});$('deleteBtn').addEventListener('click',async()=>{try{const r=await api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}/visual-logic/${encodeURIComponent(ENTITY_ID)}`,{method:'DELETE'});nodes=[];edges=[];revision=null;render();notice(r.deleted?'Visual Logic graph and its compiled behaviors were removed.':'No Visual Logic graph existed.')}catch(e){notice(e.message,true)}});$('buildBtn').addEventListener('click',async()=>{try{const r=await api(`/api/game-forge/games/${encodeURIComponent(GAME_ID)}/build`,{method:'POST'});notice(`Built ${r.runtime}. Opening private playtest…`);window.open(r.private_playtest_url,'_blank','noopener')}catch(e){notice(e.message,true)}});load();
</script></body></html>"""
    return HTMLResponse(
        html.replace("__BRAND__", safe_brand)
        .replace("__GAME_ID__", safe_game_id)
        .replace("__ENTITY_ID__", safe_entity_id)
    )


__all__ = ["router"]
